n=17; center=8; out=[]
for r in range(n):
    row=[0]*n
    if r<=center:
        left,right=center-r,center+r
        row[left]=row[right]=2
        for c in range(left+1,right):
            if (c-r-center)%4==0: row[c]=1
    else:
        for c in range(n):
            if (c-r-center)%4==0: row[c]=1
    out.append(row)
print(out)
print('dimensions',len(out),set(map(len,out)))
